const roleIds=['post','cafe','garden','bridge'],deltas={n:[0,1],e:[1,0],s:[0,-1],w:[-1,0]},directionIds=Object.keys(deltas),codes=['help','audio','together','expansion','example'],statuses=['incomplete','unstarted','ready','walking','blocked','finished'];
