const traceShape=t=>t===null||object(t)&&Array.isArray(t.commands)&&t.commands.length<=6&&t.commands.every(d=>directionIds.includes(d))&&Array.isArray(t.points)&&t.points.length>=1&&t.points.length<=7&&t.points.every(point)&&integer(t.steps,6)&&integer(t.distance,6)&&(t.blocked===null||Number.isInteger(t.blocked)&&t.blocked>=1&&t.blocked<=6)&&typeof t.arrived==='boolean';
export function validRepeatCheck(c){return object(c)&&validRepeatSource(c.source)&&oldInput(c.input)&&text(c.programLabel,1000)&&(c.expanded===null||Array.isArray(c.expanded)&&[4,6].includes(c.expanded.length)&&c.expanded.every(d=>directionIds.includes(d)))&&traceShape(c.trace)&&(c.proposedMoves===null||[4,6].includes(c.proposedMoves))&&(c.attempted===null||integer(c.attempted,6))&&(c.travelled===null||integer(c.travelled,6))&&statuses.includes(c.status)&&(c.deliveryMatch===null||typeof c.deliveryMatch==='boolean')&&typeof c.fulfilled==='boolean'&&text(c.pictureText,3000)&&text(c.traceDescription,3000)&&text(c.feedback,7500);}
export function validRepeatRound(r){return object(r)&&positive(r.id)&&validRepeatSource(r.source)&&oldInput(r)&&currentRunFits(r.source,r.block,r.count,r.run)&&typeof r.familiar==='boolean'&&Array.isArray(r.checks)&&r.checks.length<=8&&r.checks.every(validRepeatCheck);}
export function repeatView(state){const root=state.repeatDeliveries,base={root,rounds:[],earlier:[],current:null,page:'map'};if(root===undefined)return {...base,status:'missing'};if(!object(root)||root.version!==1||!repeatPages.includes(root.page)||!positive(root.current)||!positive(root.nextId)||!Array.isArray(root.seen)||!root.seen.every(id)||new Set(root.seen).size!==root.seen.length||!Array.isArray(root.rounds))return {...base,status:'unavailable'};const rounds=[],earlier=[],counts=new Map();for(const r of root.rounds)if(object(r)&&positive(r.id))counts.set(r.id,(counts.get(r.id)||0)+1);for(const r of root.rounds){if(validRepeatRound(r)&&counts.get(r.id)===1)rounds.push(r);else earlier.push(r);}return {...base,status:'ready',rounds,earlier,current:rounds.find(r=>r.id===root.current)||null,page:root.page};}
