const active=s=>repeatView(s).current;
export function resumeRepeat(state,id){const v=repeatView(state);if(!v.rounds.some(r=>r.id===id))return false;v.root.current=id;return true;}
export function setRepeatPage(state,page){const v=repeatView(state);if(!v.current||!repeatPages.includes(page))return false;v.root.page=page;return true;}
