 const trace=walkMap(source.places[source.from],expanded.slice(0,run.cursor),source.places[source.to]),status=trace.blocked!==null?'blocked':run.cursor===expanded.length?'finished':run.cursor===0?'ready':'walking',deliveryMatch=status==='blocked'?false:status==='finished'?trace.arrived:null;
