export function repeatTraceDescription(source,b,n,run){const p=repeatProgress(source,b,n,run);if(!p)return 'This working trace is unavailable.';if(p.status==='incomplete')return 'No complete two-arrow repeat program is proposed yet. Nothing has been flown.';if(p.status==='unstarted')return `${p.proposedMoves} moves are proposed, but this program has not begun. No traveled trace is recorded.`;return `Status: ${p.status}. ${p.proposedMoves} proposed moves; ${p.attempted} commands attempted; ${p.travelled} moves traveled. Visited coordinates: ${p.trace.points.map(q=>`(${q.x}, ${q.y})`).join(' → ')}.${p.trace.blocked===null?'':` Command ${p.trace.blocked} is blocked at the grid boundary; it did not travel outside.`} One traveled interval is one model meter.`;}
